// 测试扩展方法在VM模式下的更多功能

extension string {
    func repeat\(n:int\) -> string {
        result <- ""
        i <- 0
        while i < n {
            result <- result + this
            i <- i + 1
        }
        return result
    }
}

extension list {
    func sum\(\) -> int {
        total <- 0
        for item in this {
            total <- total + item
        }
        return total
    }
}

// 测试字符串扩展
text <- "Hello"
repeated <- text.repeat\(3\)
Print\("text.repeat\(3\) = " + repeated\)

// 测试列表扩展
numbers <- [1, 2, 3, 4, 5]
total <- numbers.sum\(\)
Print\("numbers.sum\(\) = " + total.ToStr\(\)\)
EOF)

