// 测试文档中的扩展方法示例

// 为 int 类型添加扩展方法
extension int {
    func double\(\) -> int {
        return this * 2
    }

    func isEven\(\) -> bool {
        return this % 2 == 0
    }
}

// 使用扩展方法
x <- 5
doubled <- x.double\(\)
isEven <- x.isEven\(\)

Print\("x.double\(\) = " + doubled.ToStr\(\)\)
Print\("x.isEven\(\) = " + isEven.ToStr\(\)\)

// 为列表添加扩展方法
extension list {
    func sum\(\) -> int {
        total <- 0
        for item in this {
            total <- total + item
        }
        return total
    }
}

// 使用
numbers <- [1, 2, 3, 4, 5]
total <- numbers.sum\(\)
Print\("numbers.sum\(\) = " + total.ToStr\(\)\)
EOF)
